import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getLiveMatches } from '@/entities/match/api';
import { Match } from '@/entities/match/types';

const MainPage = () => {
  const [matches, setMatches] = useState<Match[]>([]);

  useEffect(() => {
    const fetch = async () => {
      try {
        const data = await getLiveMatches();
        setMatches(data.slice(0, 3)); // только первые 3 матча
      } catch (err) {
        console.error('Ошибка получения матчей:', err);
      }
    };

    fetch();
  }, []);

  return (
    <div className="container text-white text-center mt-5">
      <h1 className="display-3 mb-4">SportPulse</h1>
      <p className="lead">Футбол в прямом эфире. Без рекламы. Без регистрации.</p>

      <div className="mt-4">
        <Link to="/live" className="btn btn-danger mx-2">🔴 Live</Link>
        <Link to="/upcoming" className="btn btn-warning mx-2">🟡 Предстоящие</Link>
        <Link to="/finished" className="btn btn-secondary mx-2">⚪ Завершённые</Link>
      </div>

      {matches.length > 0 && (
        <div className="mt-5">
          <h3 className="mb-3 text-start">🔥 Сейчас в эфире</h3>
          {matches.map((match, idx) => (
            <div
              key={idx}
              className="card bg-dark text-white mb-2 p-3 d-flex flex-row justify-content-between align-items-center"
            >
              <span>{match.home}</span>
              <span className="text-danger fw-bold">LIVE</span>
              <span>{match.away}</span>
            </div>
          ))}
          <Link to="/live" className="btn btn-outline-light btn-sm mt-3">Смотреть все live матчи →</Link>
        </div>
      )}
    </div>
  );
};

export default MainPage;
